import React, { useState } from 'react';
import useMediaQuery from '@mui/material';

function App() {
  const [screenWidth, setScreenWidth] = useState<number>(window.innerWidth);
  const mediaQuery = '(min-width: 768px)';
  const isLargeScreen = useMediaQuery(mediaQuery);

  const handleToggle = () => {
    setScreenWidth(prev => prev > 768 ? 600 : 800);
  };

  return (
    <div>
      <h1>useMediaQuery Demo</h1>
      <h2>Screen is {isLargeScreen ? 'Large' : 'Small'}</h2>
      <button onClick={handleToggle}>Toggle Width State</button>
    </div>
  );
}

export default App;
